import sys
input = sys.stdin.read().split()
n = int(input[0])
a = list(map(int, input[1:]))

def max_beauty(a, n):
    if n == 0:
        return max(a)
    else:
        mid = len(a) // 4
        return max(a) + max_beauty(a[:mid], n-1) + max_beauty(a[mid:2*mid], n-1) + max_beauty(a[2*mid:3*mid], n-1) + max_beauty(a[3*mid:], n-1)

print(max_beauty(a, n))
